bool UnionTraits<::ash::settings::mojom::SettingChangeValue::DataView, ::ash::settings::mojom::SettingChangeValuePtr>::Read(
    ::ash::settings::mojom::SettingChangeValue::DataView input,
    ::ash::settings::mojom::SettingChangeValuePtr* output) {
  using UnionType = ::ash::settings::mojom::SettingChangeValue;
  using Tag = UnionType::Tag;

  switch (input.tag()) {
    case Tag::kBoolValue: {
      *output = UnionType::NewBoolValue(input.bool_value());
      break;
    }
    case Tag::kIntValue: {
      *output = UnionType::NewIntValue(input.int_value());
      break;
    }
    case Tag::kStringValue: {
      std::string result_string_value;
      if (!input.ReadStringValue(&result_string_value))
        return false;

      *output = UnionType::NewStringValue(
          std::move(result_string_value));
      break;
    }
    default:

      return false;
  }
  return true;
}

